INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'greet', 'v.', '/ɡriːt/', '问候;迎接;招呼', 'The guide stood at the door to greet the visitors to the art show.', '导览员站在门口迎接来看艺术展的参观者。', 'Amazing Art', 1, 0, 'senior', 'wordlist', 'required3', 'U4', 'greet the visitors', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'broadcast', 'n./v.', '/ˈbrɔːdkɑːst/', '广播节目;电视节目;播送', 'Zack made a live broadcast from inside the famous Louvre Museum.', '扎克从著名的卢浮宫内做了一场现场直播。', 'Amazing Art', 2, 0, 'senior', 'wordlist', 'required3', 'U4', 'a live broadcast', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stair', 'n.', '/steə/', '楼梯;(一级)台阶', 'The huge statue stands at the top of the stone stairs.', '那座巨大的雕像立在石阶的顶端。', 'Amazing Art', 3, 0, 'senior', 'wordlist', 'required3', 'U4', 'at the top of the stairs', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'load', 'n.', '/ləʊd/', '某物的量;负荷;一批', 'Just get a load of that magnificent sculpture over there!', '快看那边那座宏伟的雕塑!', 'Amazing Art', 4, 0, 'senior', 'wordlist', 'required3', 'U4', 'get a load of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'battle', 'n.', '/ˈbætl/', '战斗;战役', 'The winged statue seems to celebrate the result of an ancient battle.', '那座带翅膀的雕像仿佛在庆祝一场古代战役的胜利。', 'Amazing Art', 5, 0, 'senior', 'wordlist', 'required3', 'U4', 'celebrate a battle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fold', 'v.', '/fəʊld/', '折起;对折', 'Look at how the stone dress is being folded by the wind.', '看那石雕的裙子被风吹得折叠起来的样子。', 'Amazing Art', 6, 0, 'senior', 'wordlist', 'required3', 'U4', 'fold the cloth', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sculptor', 'n.', '/ˈskʌlptə/', '雕刻家;雕塑家', 'The skill of the sculptor who made this work is just incredible.', '创作这件作品的雕塑家的技艺令人惊叹。', 'Amazing Art', 7, 0, 'senior', 'wordlist', 'required3', 'U4', 'a skilful sculptor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sculpture', 'n.', '/ˈskʌlptʃə/', '雕塑;雕像;雕刻艺术', 'A huge sculpture of a winged lady stands above the stairs.', '一座带翅膀女子的巨大雕塑矗立在楼梯之上。', 'Amazing Art', 8, 0, 'senior', 'wordlist', 'required3', 'U4', 'a huge sculpture', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'portrait', 'n.', '/ˈpɔːtrɪt/', '肖像;人物照片', 'Rembrandt painted this self-portrait about four hundred years ago.', '伦勃朗大约在四百年前画了这幅自画像。', 'Amazing Art', 9, 0, 'senior', 'wordlist', 'required3', 'U4', 'a self-portrait', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'selfie', 'n.', '/ˈselfi/', '自拍照', 'Perhaps a self-portrait was the artist''s way of taking a selfie.', '也许自画像就是那位艺术家自拍的方式。', 'Amazing Art', 10, 0, 'senior', 'wordlist', 'required3', 'U4', 'take a selfie', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'exhibition', 'n.', '/ˌeksɪˈbɪʃn/', '展出;展览;展览会', 'We saw a breathtaking exhibition of Chinese porcelain at the festival.', '我们在艺术节上看了一场令人惊叹的中国瓷器展。', 'Amazing Art', 11, 0, 'senior', 'wordlist', 'required3', 'U4', 'a breathtaking exhibition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gallery', 'n.', '/ˈɡæləri/', '美术馆;画廊;展览馆', 'The cleaners in the gallery threw away the artwork by mistake.', '美术馆的清洁工误把那件艺术品扔掉了。', 'Amazing Art', 12, 0, 'senior', 'wordlist', 'required3', 'U4', 'an art gallery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'treasure', 'n.', '/ˈtreʒə/', '珍宝;宝藏;珍品', 'The Louvre is full of some of the most amazing treasures on Earth.', '卢浮宫里满是地球上最令人惊叹的一些珍宝。', 'Amazing Art', 13, 0, 'senior', 'wordlist', 'required3', 'U4', 'amazing treasures', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'masterpiece', 'n.', '/ˈmɑːstəpiːs/', '杰作;名作', 'Night-Shining White is regarded as Han Gan''s greatest masterpiece.', '《照夜白》被视为韩干最伟大的杰作。', 'Amazing Art', 14, 0, 'senior', 'wordlist', 'required3', 'U4', 'an artist''s masterpiece', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'neighbourhood', 'n.', '/ˈneɪbəhʊd/', '社区;街区;街坊', 'Original buildings are being built in every neighbourhood of the city.', '城市的每个街区都在建造别具一格的建筑。', 'Amazing Art', 15, 0, 'senior', 'wordlist', 'required3', 'U4', 'in every neighbourhood', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'graffiti', 'n.', '/ɡrəˈfiːti/', '(墙上的)涂鸦', 'Some people find graffiti too random, but I love its bright colours.', '有些人觉得涂鸦太随意,但我喜欢它鲜艳的色彩。', 'Amazing Art', 16, 0, 'senior', 'wordlist', 'required3', 'U4', 'colourful graffiti', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'embroidery', 'n.', '/ɪmˈbrɔɪdəri/', '刺绣;刺绣品', 'A woman used a needle and thread to do some lovely embroidery.', '一位女子用针线绣出了漂亮的刺绣。', 'Amazing Art', 17, 0, 'senior', 'wordlist', 'required3', 'U4', 'do some embroidery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'seal', 'n.', '/siːl/', '印章;图章', 'The old man showed me how a stone seal is carved and stamped.', '那位老人给我演示了石印章如何被刻制并盖印。', 'Amazing Art', 18, 0, 'senior', 'wordlist', 'required3', 'U4', 'carve a seal', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'calligraphy', 'n.', '/kəˈlɪɡrəfi/', '书法;书法艺术', 'An old man was writing Chinese calligraphy in a free and elegant style.', '一位老人正以自由而优雅的笔法书写中国书法。', 'Amazing Art', 19, 0, 'senior', 'wordlist', 'required3', 'U4', 'Chinese calligraphy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'porcelain', 'n.', '/ˈpɔːsəlɪn/', '瓷器;瓷', 'I bought a blue porcelain cup and saucer at the art festival.', '我在艺术节上买了一只蓝色的瓷杯和茶碟。', 'Amazing Art', 20, 0, 'senior', 'wordlist', 'required3', 'U4', 'a porcelain cup', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'demonstrate', 'v.', '/ˈdemənstreɪt/', '示范;演示;表明', 'At each stand, artists could demonstrate their skills to the visitors.', '在每个展位上,艺术家都能向参观者示范他们的技艺。', 'Amazing Art', 21, 0, 'senior', 'wordlist', 'required3', 'U4', 'demonstrate a skill', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'vividly', 'adv.', '/ˈvɪvɪdli/', '生动地;鲜明地', 'The blue bowl vividly showed a dragon playing with a ball.', '那只青花碗生动地描绘了一条龙戏珠的图案。', 'Amazing Art', 22, 0, 'senior', 'wordlist', 'required3', 'U4', 'vividly illustrate', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'needle', 'n.', '/ˈniːdl/', '缝衣针;针', 'She used a needle and some thread to make a tiny flower.', '她用针和线绣出了一朵小花。', 'Amazing Art', 23, 0, 'senior', 'wordlist', 'required3', 'U4', 'a needle and thread', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'elegant', 'adj.', '/ˈelɪɡənt/', '高雅的;优美的;雅致的', 'His calligraphy was so free and elegant that everyone admired it.', '他的书法自由又优雅,人人都很赞赏。', 'Amazing Art', 24, 0, 'senior', 'wordlist', 'required3', 'U4', 'an elegant style', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'carve', 'v.', '/kɑːv/', '刻;雕刻', 'Chinese characters are carved into small squares of stone.', '汉字被刻进一小块块的石头里。', 'Amazing Art', 25, 0, 'senior', 'wordlist', 'required3', 'U4', 'carve into stone', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'contemporary', 'adj.', '/kənˈtempərəri/', '当代的;现代的;同时代的', 'Contemporary art often raises the question, "Is it really art?"', '当代艺术常常引出一个问题:“这真的是艺术吗?”', 'Amazing Art', 26, 0, 'senior', 'wordlist', 'required3', 'U4', 'contemporary art', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cigarette', 'n.', '/ˌsɪɡəˈret/', '香烟;纸烟', 'The cleaners mistook the pile of cigarette ends for rubbish.', '清洁工把那堆烟头当成了垃圾。', 'Amazing Art', 27, 0, 'senior', 'wordlist', 'required3', 'U4', 'cigarette ends', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'lack', 'v./n.', '/læk/', '缺乏;没有;缺少', 'Some people say contemporary art lacks skill and real meaning.', '有些人说当代艺术缺乏技巧和真正的内涵。', 'Amazing Art', 28, 0, 'senior', 'wordlist', 'required3', 'U4', 'lack meaning', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'stimulate', 'v.', '/ˈstɪmjuleɪt/', '刺激;激发;促进', 'Others argue that such art can stimulate new discussions.', '另一些人则认为这类艺术能激发新的讨论。', 'Amazing Art', 29, 0, 'senior', 'wordlist', 'required3', 'U4', 'stimulate discussion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'magnificent', 'adj.', '/mæɡˈnɪfɪsnt/', '宏伟的;壮丽的;极好的', 'What a magnificent horse the painter has shown in this work!', '画家在这幅作品中画出了一匹多么壮美的马啊!', 'Amazing Art', 30, 0, 'senior', 'wordlist', 'required3', 'U4', 'a magnificent horse', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bare', 'v.', '/beə/', '使暴露;露出', 'The painted horse seems to bare its teeth with great power.', '画中的马仿佛龇着牙,充满力量。', 'Amazing Art', 31, 0, 'senior', 'wordlist', 'required3', 'U4', 'bare its teeth', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'hoof', 'n.', '/huːf/', '(马等动物的)蹄', 'We can almost feel the power in the horse''s kicking hooves.', '我们几乎能感受到那马蹄踢动时的力量。', 'Amazing Art', 32, 0, 'senior', 'wordlist', 'required3', 'U4', 'kicking hooves', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'wine', 'n.', '/waɪn/', '葡萄酒;酒', 'Young Han Gan had to work in a local wine shop to help his family.', '年轻的韩干不得不在当地一家酒坊干活以补贴家用。', 'Amazing Art', 33, 0, 'senior', 'wordlist', 'required3', 'U4', 'a wine shop', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'dirt', 'n.', '/dɜːt/', '灰尘;尘土;泥土', 'Han Gan used a stick to draw pictures in the dirt by the gate.', '韩干用一根树枝在门边的泥土上画画。', 'Amazing Art', 34, 0, 'senior', 'wordlist', 'required3', 'U4', 'draw in the dirt', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sponsor', 'v.', '/ˈspɒnsə/', '资助;赞助', 'Wang Wei decided to sponsor the young man to study painting.', '王维决定资助这位年轻人去学画。', 'Amazing Art', 35, 0, 'senior', 'wordlist', 'required3', 'U4', 'sponsor a young man', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'emperor', 'n.', '/ˈempərə/', '皇帝', 'Han Gan was finally chosen to serve the emperor in the royal palace.', '韩干最终被选中在皇宫中侍奉皇帝。', 'Amazing Art', 36, 0, 'senior', 'wordlist', 'required3', 'U4', 'serve the emperor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fond', 'adj.', '/fɒnd/', '喜爱的;喜欢的', 'The Tang emperors were very fond of horses.', '唐代的皇帝们非常喜爱马。', 'Amazing Art', 37, 0, 'senior', 'wordlist', 'required3', 'U4', 'be fond of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'frequent', 'adj.', '/ˈfriːkwənt/', '经常发生的;频繁的', 'Han Gan was a frequent visitor to the royal stables.', '韩干是皇家马厩的常客。', 'Amazing Art', 38, 0, 'senior', 'wordlist', 'required3', 'U4', 'a frequent visitor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'majesty', 'n.', '/ˈmædʒəsti/', '(对君主的尊称)陛下;威严', '"I have my own teachers, Your Majesty," the artist replied.', '“陛下,我有自己的老师,”这位画家答道。', 'Amazing Art', 39, 0, 'senior', 'wordlist', 'required3', 'U4', 'Your Majesty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gallop', 'v.', '/ˈɡæləp/', '(马)飞奔;疾驰', 'People said that Han Gan''s horses could gallop off the paper.', '人们说韩干画的马仿佛能从纸上飞奔出来。', 'Amazing Art', 40, 0, 'senior', 'wordlist', 'required3', 'U4', 'gallop off the paper', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'vase', 'n.', '/vɑːz/', '花瓶', 'Van Gogh''s painting shows yellow sunflowers in a vase.', '梵高的这幅画描绘了花瓶里的黄色向日葵。', 'Amazing Art', 41, 0, 'senior', 'wordlist', 'required3', 'U4', 'sunflowers in a vase', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'mostly', 'adv.', '/ˈməʊstli/', '大部分;主要地;通常', 'This painting is done mostly in three shades of yellow.', '这幅画主要由三种深浅不同的黄色绘成。', 'Amazing Art', 42, 0, 'senior', 'wordlist', 'required3', 'U4', 'mostly in yellow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'shade', 'n.', '/ʃeɪd/', '(色彩的)浓淡;深浅;色度;阴凉处', 'The colours range from bright yellows to brownish shades.', '色彩从明黄渐变到带褐的深浅色调。', 'Amazing Art', 43, 0, 'senior', 'wordlist', 'required3', 'U4', 'shades of yellow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'inspiration', 'n.', '/ˌɪnspəˈreɪʃn/', '灵感;启发;鼓舞人心的人(或事物)', 'The real horses gave Han Gan plenty of inspiration for his art.', '真实的马给了韩干充足的创作灵感。', 'Amazing Art', 44, 0, 'senior', 'wordlist', 'required3', 'U4', 'plenty of inspiration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'admiration', 'n.', '/ˌædməˈreɪʃn/', '钦佩;赞赏;羡慕', 'Su Shi expressed his admiration for Han Gan as a master painter.', '苏轼表达了对画马大师韩干的钦佩。', 'Amazing Art', 45, 0, 'senior', 'wordlist', 'required3', 'U4', 'express admiration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'get a load of', 'phr.', '/ˌɡet ə ˈləʊd əv/', '注意;仔细看(表示惊讶或羡慕)', 'Get a load of that winged statue above the stairs!', '瞧瞧楼梯上方那座带翅膀的雕像!', 'Amazing Art', 46, 0, 'senior', 'wordlist', 'required3', 'U4', 'get a load of that', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'seal cutting', 'phr.', '/ˈsiːl ˌkʌtɪŋ/', '篆刻', 'In seal cutting, names are carved into small squares of stone.', '在篆刻中,人名被刻进一小块块的石头里。', 'Amazing Art', 47, 0, 'senior', 'wordlist', 'required3', 'U4', 'the art of seal cutting', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'be fond of', 'phr.', '/biː ˈfɒnd əv/', '喜欢;喜爱', 'It is wonderful to be fond of art and to visit galleries often.', '喜爱艺术、常去看画展是件很美好的事。', 'Amazing Art', 48, 0, 'senior', 'wordlist', 'required3', 'U4', 'be fond of art', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u4.01', '①is/are being done(此刻正在被进行的动作)', 'A2', 10, '外研社版必修第三册 U4 — 主语是动作的承受者、且动作此刻正在进行(right now / at the moment / look / listen)时,用 am/is/are being + 过去分词。单数主语用 is being,复数用 are being。', 1, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u4.02', '②现在进行被动 vs 现在进行主动', 'A2', 10, '外研社版必修第三册 U4 — 同样表示此刻正在进行:主语若是动作的发出者用 is/are doing(主动);主语若是动作的承受者用 is/are being done(被动)。再按主语单复数定 is/are。', 2, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f3u4.03', '③现在进行被动 vs 一般现在被动(此刻 vs 习惯)', 'A2', 10, '外研社版必修第三册 U4 — 都是被动:此刻正在被做(right now / at the moment / look)用 is/are being done;表习惯/经常(every day / usually / once a year)用 is/are done。按时间状语判断时态,再按单复数定 be 动词。', 3, 'required3', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Look — the old portrait ____ by two experts in the gallery right now.', 'is being cleaned', 'is cleaning', 'is cleaned', 'was being cleaned', 'A', '此刻正在进行、画是被清洗的对象,用现在进行被动 is being cleaned;主动形式把画当成施动者,一般现在被动不表此刻进行,过去进行与 right now 矛盾。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'At the moment, several new sculptures ____ in the main hall for the exhibition.', 'are arranging', 'are being arranged', 'are arranged', 'were being arranged', 'B', '复数主语、此刻正被摆放,用 are being arranged;主动表示雕塑自己在摆,一般现在被动不表正在进行,过去进行与 at the moment 矛盾。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Be quiet, please — a live broadcast ____ from the museum at this very moment.', 'is making', 'is made', 'is being made', 'was being made', 'C', '此刻正在被制作的节目,用 is being made;broadcast 不会自己制作,一般现在被动不表此刻进行,过去进行与 at this very moment 不符。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Right now, the magnificent vase ____ to a safer room by the staff.', 'is moving', 'is moved', 'has been moving', 'is being moved', 'D', '花瓶是被搬动的对象、此刻正在进行,用 is being moved;主动表示花瓶自己移动,一般现在被动不表进行,现在完成进行语态也不通。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Listen! The story behind the painting ____ to the visitors by the guide now.', 'is being told', 'is telling', 'is told', 'was being told', 'A', '故事是被讲述的内容、此刻正在进行,用 is being told;主动把故事当讲述者,一般现在被动不表进行,过去进行与 now 矛盾。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'At this moment, colourful pictures ____ on the pub wall by some young artists.', 'are painting', 'are being painted', 'are painted', 'were being painted', 'B', '复数主语、画是被画的对象、此刻进行,用 are being painted;主动表示画自己在画,一般现在被动不表此刻,过去进行与 at this moment 不符。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Look over there — a huge stone horse ____ by the sculptor right now.', 'is carving', 'is carved', 'is being carved', 'has been carved', 'C', '石马是被雕刻的对象、此刻进行,用 is being carved;主动把马当施动者,一般现在被动不表进行,现在完成被动表已完成而非正在进行。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Currently, the elegant porcelain cups ____ in shades of blue in the workshop.', 'are painting', 'are painted', 'were being painted', 'are being painted', 'D', '复数主语、杯子是被绘的对象、此刻进行,用 are being painted;主动表示杯子自己作画,一般现在被动不表此刻,过去进行与 currently 不符。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Don''t touch it — the wet canvas ____ to the frame by the workers at the moment.', 'is being fixed', 'is fixing', 'is fixed', 'was being fixed', 'A', '画布是被固定的对象、此刻进行,用 is being fixed;主动把画布当施动者,一般现在被动不表进行,过去进行与 at the moment 矛盾。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Right now, a famous self-portrait ____ in the contemporary art show downstairs.', 'is displaying', 'is being displayed', 'is displayed', 'had been displayed', 'B', '自画像是被展出的对象、此刻进行,用 is being displayed;主动表示画自己展出,一般现在被动不表此刻,过去完成被动与 right now 不符。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Look — the dragon design ____ onto the white bowl by the artist this very second.', 'is carving', 'is carved', 'is being carved', 'was being carved', 'C', '图案是被雕刻的对象、此刻进行,用 is being carved;主动把图案当施动者,一般现在被动不表进行,过去进行与 this very second 矛盾。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'At the moment, a small seal ____ into a square of stone by the old master.', 'is cutting', 'is cut', 'has been cutting', 'is being cut', 'D', '印章是被刻的对象、此刻进行,用 is being cut;主动表示印章自己刻,一般现在被动不表此刻,完成进行语态不通。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Quiet, everyone — Han Gan''s life story ____ to the class by our teacher right now.', 'is being introduced', 'is introducing', 'is introduced', 'was being introduced', 'A', '故事是被介绍的内容、此刻进行,用 is being introduced;主动把故事当介绍者,一般现在被动不表进行,过去进行与 right now 矛盾。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Right now, original buildings ____ in our neighbourhood by local workers.', 'are building', 'are being built', 'are built', 'were being built', 'B', '复数主语、楼房是被建造的对象、此刻进行,用 are being built;主动表示楼自己建,一般现在被动不表此刻,过去进行与 right now 不符。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'At this moment, the trees in the park ____ into animal shapes by the gardeners.', 'are trimming', 'are trimmed', 'are being trimmed', 'had been trimmed', 'C', '复数主语、树是被修剪的对象、此刻进行,用 are being trimmed;主动表示树自己修剪,一般现在被动不表此刻,过去完成被动与 at this moment 不符。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Be careful — fresh paint ____ to the sculptor''s new work right now.', 'is adding', 'is added', 'was being added', 'is being added', 'D', '颜料是被添加的对象、此刻进行,用 is being added;主动把颜料当施动者,一般现在被动不表进行,过去进行与 right now 矛盾。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Listen — a short film about calligraphy ____ to the audience at the moment.', 'is being shown', 'is showing', 'is shown', 'was being shown', 'A', '影片是被播放的对象、此刻进行,用 is being shown;主动表示影片自己放映对象错位,一般现在被动不表此刻,过去进行与 at the moment 不符。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Right now, the visitors ____ around the crowded hall by the moving crowd.', 'are pushing', 'are being pushed', 'are pushed', 'were being pushed', 'B', '复数主语、参观者是被推挤的对象、此刻进行,用 are being pushed;主动表示他们在推别人,一般现在被动不表此刻,过去进行与 right now 矛盾。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'Look — a delicate flower ____ onto the white vase by the painter this minute.', 'is drawing', 'is drawn', 'is being drawn', 'has been drawing', 'C', '花样是被画的对象、此刻进行,用 is being drawn;主动把花当施动者,一般现在被动不表进行,完成进行语态不通。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.01'), 'At the moment, the museum''s treasures ____ for the new exhibition by the team.', 'are preparing', 'are prepared', 'were being prepared', 'are being prepared', 'D', '复数主语、珍宝是被准备的对象、此刻进行,用 are being prepared;主动表示珍宝自己准备,一般现在被动不表此刻,过去进行与 at the moment 不符。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'Right now, the young artist ____ a beautiful picture on the pub wall.', 'is painting', 'is being painted', 'are painting', 'are being painted', 'A', '主语 artist 是动作的发出者、单数、此刻进行,用主动 is painting;被动会把画家当成被画对象,复数形式与单数主语不符。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'At the moment, a beautiful picture ____ on the pub wall by the young artist.', 'is painting', 'is being painted', 'are being painted', 'are painting', 'B', '主语 picture 是动作的承受者、单数、此刻进行,用被动 is being painted;主动会把画当作画者,复数形式与单数主语不符。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'Look — the sculptor ____ a magnificent horse out of stone right now.', 'is being carved', 'are carving', 'is carving', 'are being carved', 'C', '主语 sculptor 是雕刻者、单数、此刻进行,用主动 is carving;被动会把雕刻家当成被刻对象,复数与单数主语不符。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'Look — a magnificent horse ____ out of stone by the sculptor right now.', 'is carving', 'are being carved', 'are carving', 'is being carved', 'D', '主语 horse 是被刻的对象、单数、此刻进行,用被动 is being carved;主动会把石马当雕刻者,复数与单数主语不符。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'At this moment, several workers ____ the heavy statue into the main hall.', 'are moving', 'are being moved', 'is moving', 'is being moved', 'A', '主语 workers 是搬运者、复数、此刻进行,用主动 are moving;被动会把工人当成被搬对象,单数形式与复数主语不符。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'At this moment, the heavy statue ____ into the main hall by several workers.', 'is moving', 'is being moved', 'are being moved', 'are moving', 'B', '主语 statue 是被搬的对象、单数、此刻进行,用被动 is being moved;主动会把雕像当搬运者,复数与单数主语不符。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'Right now, the guide ____ the story behind the painting to a big group.', 'is being told', 'are telling', 'is telling', 'are being told', 'C', '主语 guide 是讲述者、单数、此刻进行,用主动 is telling;被动会把导览员当成被讲对象,复数与单数主语不符。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'Right now, the story behind the painting ____ to a big group by the guide.', 'is telling', 'are being told', 'are telling', 'is being told', 'D', '主语 story 是被讲述的内容、单数、此刻进行,用被动 is being told;主动会把故事当讲述者,复数与单数主语不符。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'Currently, two careful experts ____ the precious vase in the quiet workshop.', 'are repairing', 'are being repaired', 'is repairing', 'is being repaired', 'A', '主语 experts 是修复者、复数、此刻进行,用主动 are repairing;被动会把专家当成被修对象,单数与复数主语不符。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'Currently, the precious vase ____ by two experts in the quiet workshop.', 'is repairing', 'is being repaired', 'are being repaired', 'are repairing', 'B', '主语 vase 是被修复的对象、单数、此刻进行,用被动 is being repaired;主动会把花瓶当修复者,复数与单数主语不符。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.02'), 'Look — the old master ____ his own name onto a square of soft stone.', 'is being carved', 'are carving', 'is carving', 'are being carved', 'C', '主语 master 是雕刻者、单数、此刻进行,用主动 is carving;被动会把老师傅当成被刻对象,复数与单数主语不符。', 2, 11, 'mcq');
