INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.03'), 'Every winter, the oldest paintings ____ to protect them from the cold air.', 'are being moved', 'is moved', 'is being moved', 'are moved', 'D', 'every winter 表习惯、复数,用一般现在被动 are moved;现在进行被动表此刻进行与习惯矛盾,单数 be 动词与复数主语不符。', 2, 16, 'mcq');
