INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.03'), 'Each weekend, simple art classes ____ to local families for free.', 'are being given', 'are given', 'is given', 'is being given', 'B', 'each weekend 表习惯、复数,用一般现在被动 are given;现在进行被动表此刻进行与习惯矛盾,单数 be 动词与复数主语不符。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.03'), 'At this very moment, fresh flowers ____ around the magnificent statue.', 'are arranged', 'is being arranged', 'are being arranged', 'is arranged', 'C', 'at this very moment 表此刻进行、复数,用现在进行被动 are being arranged;一般现在被动表习惯,单数 be 动词与复数主语不符。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required3' AND unit='U4' AND code='f3u4.03'), 'Usually, the small seal ____ into a square of soft stone by the master.', 'is being cut', 'are cut', 'are being cut', 'is cut', 'D', 'usually 表习惯、单数,用一般现在被动 is cut;现在进行被动表此刻进行与 usually 矛盾,复数 be 动词与单数主语不符。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Live from the Louvre', 'Hi, it''s Zack, and greetings from Paris! This broadcast is being brought to you from one of the largest museums on Earth, the Louvre. At the top of these stone stairs, get a load of that huge sculpture! It is the Winged Victory of Samothrace. She looks as if she has just flown down from the sky and landed on a ship. Her head and arms are missing, but you can still imagine her holding her arms up high to celebrate a battle. Just look at how her stone dress is being folded by the wind. I really cannot believe she is made of stone, for the skill of the sculptor is incredible. There are so many people here that I am being pushed around quite a bit. Coming up next is the one and only Mona Lisa, which is smaller than you would expect and protected by glass.', '记叙·卢浮宫现场直播', 149, '[{"q":"Where is Zack speaking from?","answer":"A","options":["Inside one of the world''s biggest museums.","On a busy street in Paris.","At a small private gallery.","From a television studio."],"explanation":"原文说直播来自地球上最大的博物馆之一卢浮宫,即世界上最大的博物馆之一。"},{"q":"Why is Zack being pushed about as he speaks?","answer":"B","options":["Because the floor is wet and slippery.","Because the hall is very crowded with people.","Because the guards are moving him on.","Because a storm has hit the building."],"explanation":"原文 ''There are so many people here that I am being pushed around'',因人太多而被挤,即大厅很拥挤。"},{"q":"What does Zack say about the Mona Lisa?","answer":"A","options":["It is less large than most people imagine.","It hangs in the open with no cover.","It is the biggest work in the museum.","It has lost its head and arms."],"explanation":"原文 ''smaller than you would expect'',即比人们想象的要小;玻璃保护说明并非露天,失去头臂的是雕像而非蒙娜丽莎。"}]'::jsonb, '[{"word":"broadcast","cn":"直播节目"},{"word":"sculptor","cn":"雕塑家"},{"word":"fold","cn":"折叠"}]'::jsonb, 2, 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Han Gan and His Horses', 'Born into a poor family in the early Tang Dynasty, young Han Gan had to work in a local wine shop to support his family. His talent was discovered by accident. One day he was sent to collect payment from the poet Wang Wei. While waiting at the gate, he used a stick to draw in the dirt and was seen by the poet himself. Wang Wei decided to sponsor the young man to study painting. Later, Han Gan was chosen to serve the emperor. The Tang emperors were very fond of horses, so the animal was a frequent subject for artists. Most painters at that time simply copied earlier works, but Han Gan''s method was different: he observed real horses. He even moved in with the stable workers, and the animals gave him plenty of inspiration. When the emperor told him to take a master as his teacher, he replied that all the horses in the royal stables were his true teachers.', '记叙·画马大师韩干', 163, '[{"q":"How was Han Gan''s painting talent first noticed?","answer":"B","options":["He won a competition at the royal palace.","A poet happened to see him drawing on the ground.","A master came to teach him at home.","The emperor visited his family''s wine shop."],"explanation":"原文 Wang Wei 在门口看到他用树枝在土里画画,即一位诗人偶然看见他在地上画画。"},{"q":"How did Han Gan''s way of learning differ from other painters?","answer":"C","options":["He never looked at any real horses.","He only painted from his imagination.","He studied living horses instead of copying old pictures.","He refused to study painting at all."],"explanation":"原文说别人多临摹前人作品,而韩干观察真马,即研究活马而非临摹旧画。"},{"q":"What did Han Gan mean when he spoke to the emperor about teachers?","answer":"D","options":["He had never had any teacher in his life.","He wished to leave the royal palace soon.","He thought no one could paint horses well.","The real horses he watched were what taught him most."],"explanation":"他说马厩里的马才是他真正的老师,意为他观察的真马教会了他最多。"}]'::jsonb, '[{"word":"sponsor","cn":"资助"},{"word":"emperor","cn":"皇帝"},{"word":"inspiration","cn":"灵感"}]'::jsonb, 2, 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Festival of Chinese Art Forms', 'Yesterday I went to an amazing Chinese art festival, where artists could demonstrate their skills and teach the visitors. The first thing that caught my attention was a fifteenth-century bowl in a breathtaking exhibition of porcelain. It vividly showed a dragon playing with a ball. Then I tried paper cutting, which means making images out of paper. It was difficult but great fun, and I managed to make one shaped like a fish. At the next stand, a woman was using a needle and thread to do some embroidery, and it looked so pretty. Later I saw two elegant Chinese paintings of a pine tree and some bamboo hanging on the wall. An old man was writing calligraphy in a wonderfully free style. Another man showed me how seal cutting works: Chinese characters are carved into small squares of stone and then stamped onto paper with ink. He even made one with my name in Chinese, which was awesome.', '记叙·中国艺术形式体验', 159, '[{"q":"What did the writer first notice at the festival?","answer":"A","options":["An old painted bowl shown in a porcelain display.","A woman doing colourful embroidery.","An old man writing calligraphy.","A fish made out of cut paper."],"explanation":"原文说最先吸引注意的是瓷器展中一只十五世纪的碗,即瓷器展里的一只古碗。"},{"q":"What does the passage say about seal cutting?","answer":"B","options":["It is a way of painting bamboo and pine trees.","Characters are cut into stone and then pressed onto paper.","It uses a needle and thread to make pictures.","It means folding paper into animal shapes."],"explanation":"原文 ''汉字被刻进小石块再蘸墨盖到纸上'',即把字刻进石头再印到纸上;其余分别是国画/刺绣/剪纸。"},{"q":"How did the writer feel about trying paper cutting?","answer":"C","options":["It was easy and rather boring.","It was impossible and not worth doing.","It was hard yet enjoyable at the same time.","It was frightening and unpleasant."],"explanation":"原文 ''difficult but great fun'',即虽难却很有乐趣。"}]'::jsonb, '[{"word":"demonstrate","cn":"示范"},{"word":"embroidery","cn":"刺绣"},{"word":"seal cutting","cn":"篆刻"}]'::jsonb, 2, 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Is It Really Art?', 'Since it began in the late twentieth century, the Contemporary Art Movement has raised many questions, with people asking, "Is it really art?" This happened in 1999 with the British artist Tracey Emin''s work My Bed, which was quite literally her own unmade bed. Then, in 2015, cleaners in an Italian gallery threw away an art piece, mistaking the pile of empty bottles, cigarette ends and pieces of coloured paper for rubbish. Some people say that contemporary art lacks skill, meaning and real value, and that anyone could make such works. Others argue that its worth lies in its power to stimulate new discussions and to change the way we understand everyday objects, such as water pipes and iron wires. Whatever side you take, one thing is clear: this kind of art makes people stop, look and think. Perhaps that is exactly what the artists want their viewers to do.', '议论·当代艺术之争', 150, '[{"q":"Why did the cleaners throw the artwork away in 2015?","answer":"D","options":["They were told to clean the gallery walls.","They disliked the colour of the paper.","They wanted to sell the bottles for money.","They believed the objects were just waste."],"explanation":"原文说清洁工把瓶子烟头等当成垃圾,即以为那些东西是废物。"},{"q":"What do supporters of contemporary art believe?","answer":"A","options":["It can spark fresh discussion and new ways of seeing.","It is always made with the highest skill.","It should only use expensive materials.","It has no connection to everyday life."],"explanation":"原文说其价值在于激发新讨论、改变我们对日常物品的理解,即引发新讨论和新视角。"},{"q":"What is the writer''s final point about this kind of art?","answer":"B","options":["It is certainly a waste of time.","It pushes people to pause and reflect.","It will soon disappear completely.","It can only be enjoyed by experts."],"explanation":"末段说这类艺术让人停下、观看、思考,即促使人们停下来反思。"}]'::jsonb, '[{"word":"contemporary","cn":"当代的"},{"word":"lack","cn":"缺乏"},{"word":"stimulate","cn":"激发"}]'::jsonb, 2, 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Van Gogh''s Sunflowers', 'Van Gogh''s sunflower paintings are among his most famous works, and this one was finished in Arles in 1889. It shows sunflowers standing in a vase, painted mostly in three shades of yellow. The colours of the flowers range from bright yellows to brownish yellows, which suggests that the flowers are at different stages of life. Some are fresh and open, while others are beginning to fade. These paintings held a special meaning for Van Gogh. When his friend Paul Gauguin, who was also a famous painter, came to live with him for a while, Van Gogh hung the first two sunflower pictures in his guest''s room to make him feel welcome. To many people, the warm colours seem to glow with light and life, even though the artist himself was often poor and unhappy. Today the sunflowers are loved around the world, and copies of them are sold in shops far from France.', '说明·梵高《向日葵》', 154, '[{"q":"What do the different shades of yellow suggest?","answer":"C","options":["The painter ran out of other colours.","The flowers were painted at night.","The flowers are at various points in their lives.","The vase was made of gold."],"explanation":"原文说颜色从明黄到褐黄,表明花处于不同的生命阶段,即处于不同时期。"},{"q":"Why did Van Gogh hang the first two sunflower paintings in the guest room?","answer":"D","options":["To sell them to a passing buyer.","To hide them from the public.","To protect them from sunlight.","To make his visiting friend feel welcome."],"explanation":"原文说为了欢迎来同住的朋友高更,即让来访的朋友感到受欢迎。"},{"q":"What does the passage suggest about Van Gogh''s own life?","answer":"A","options":["He often had little money and was unhappy.","He was rich and famous while alive.","He never had any close friends.","He disliked the colour yellow."],"explanation":"原文 ''the artist himself was often poor and unhappy'',即他常常贫穷而不快乐。"}]'::jsonb, '[{"word":"vase","cn":"花瓶"},{"word":"shade","cn":"(色彩)深浅"},{"word":"mostly","cn":"主要地"}]'::jsonb, 2, 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Art Is All Around Us', 'Do you think that going to a museum is the only way to see art? Actually, art is everywhere around us. On the walls of my local pub, for example, young people are painting beautiful pictures full of colour. Some people find such graffiti too random and do not like it, but I really enjoy its bright shades. Even trees can become art. In our neighbourhood, some gardeners are trimming trees into interesting shapes, like animals or clouds, so that an ordinary park turns into an open-air gallery. And if you look up, you will see that builders are putting up original, impressive buildings in street after street. None of these works sits behind glass in a quiet hall, yet each one is being created with real care and imagination. So next time you walk down your own street, remember to slow down. Great art may be waiting for you in the most everyday places.', '议论·身边的艺术', 155, '[{"q":"What is the main idea of the passage?","answer":"B","options":["Only museums can hold true works of art.","Art can be found in many ordinary, everyday places.","Graffiti should be removed from city walls.","Trees are too plain to be called art."],"explanation":"全文强调艺术处处可见,即艺术存在于许多平常的地方。"},{"q":"How does the writer feel about the graffiti on the pub walls?","answer":"C","options":["He thinks it is ugly and messy.","He wishes it would be painted over.","He likes the bright colours of it.","He has never really noticed it."],"explanation":"原文 ''I really enjoy its bright shades'',即喜欢它鲜艳的颜色。"},{"q":"Why does the writer mention the shaped trees in the park?","answer":"D","options":["To complain that the gardeners waste time.","To explain how to grow healthier trees.","To prove that parks are usually boring.","To show how everyday spots can become art."],"explanation":"举修剪成形的树是为了说明平常之地也能变成艺术,即日常空间也能成为艺术。"}]'::jsonb, '[{"word":"graffiti","cn":"涂鸦"},{"word":"neighbourhood","cn":"社区"},{"word":"gallery","cn":"美术馆"}]'::jsonb, 2, 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'A Visit to the Art Museum', 'Last Saturday my class (1)____ a famous art museum in the city. As soon as we (2)____ inside, a friendly guide came to (3)____ us at the door. She told us that thousands of (4)____ are kept in the building, which was once a royal palace. We walked up the wide stone (5)____ to the first floor, where the most famous works hang. My favourite was a (6)____ of an old king, painted hundreds of years ago. The guide explained that the picture was being (7)____ by experts to keep its colours bright. In another room, we saw beautiful blue-and-white (8)____ cups decorated with dragons. Before we left, I bought a small (9)____ of my favourite painting to put on my wall. It was a wonderful day, and I now understand why so many people are (10)____ of visiting museums.', 140, 2, '[{"q":"1","answer":"A","options":["visited","sold","cooked","drove"],"explanation":"visit a museum 参观博物馆。"},{"q":"2","answer":"B","options":["slept","stepped","shouted","swam"],"explanation":"step inside 走进里面。"},{"q":"3","answer":"C","options":["fold","carve","greet","sell"],"explanation":"come to greet us 来迎接我们。"},{"q":"4","answer":"D","options":["mistakes","holidays","accidents","treasures"],"explanation":"thousands of treasures 数千件珍宝。"},{"q":"5","answer":"A","options":["stairs","rivers","clouds","songs"],"explanation":"stone stairs 石阶。"},{"q":"6","answer":"B","options":["recipe","portrait","ticket","password"],"explanation":"a portrait of an old king 一幅老国王的肖像。"},{"q":"7","answer":"C","options":["eaten","driven","repaired","sung"],"explanation":"was being repaired 正在被修复。"},{"q":"8","answer":"D","options":["woollen","rubber","paper","porcelain"],"explanation":"blue-and-white porcelain cups 青花瓷杯。"},{"q":"9","answer":"A","options":["copy","noise","smell","storm"],"explanation":"a small copy of the painting 一幅画的小复制品。"},{"q":"10","answer":"B","options":["ready","fond","able","willing"],"explanation":"be fond of doing 喜欢做某事;ready/able/willing 后接 to do,不接 of doing。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'Learning Calligraphy from Grandfather', 'When I was ten, my grandfather began to (1)____ me Chinese calligraphy. At first, holding the brush felt strange, and my hand would not (2)____ the way I wanted. Grandfather was very (3)____, and he never shouted when I made a mistake. He told me that good calligraphy looks (4)____, like a slow dance on paper. Every (5)____ after school, I practised the same character again and again. Slowly, my lines became smoother and more (6)____. Grandfather said that calligraphy could (7)____ the mind and help a busy person feel peaceful. One day he gave me a small red (8)____ with my name carved on it, so that I could stamp my own works. I felt so (9)____ of that little stone. Now, years later, I still (10)____ calligraphy whenever I feel worried, and it always brings me peace.', 139, 2, '[{"q":"1","answer":"C","options":["sell","drive","teach","throw"],"explanation":"teach me calligraphy 教我书法。"},{"q":"2","answer":"D","options":["sleep","sing","cook","move"],"explanation":"my hand would not move 我的手不听使唤。"},{"q":"3","answer":"A","options":["patient","angry","lazy","noisy"],"explanation":"never shouted 说明他很有耐心 patient。"},{"q":"4","answer":"B","options":["ugly","elegant","heavy","dark"],"explanation":"looks elegant, like a slow dance 看起来优雅。"},{"q":"5","answer":"C","options":["winter","mistake","evening","corner"],"explanation":"every evening after school 每天放学后的傍晚。"},{"q":"6","answer":"D","options":["broken","empty","tired","beautiful"],"explanation":"smoother and more beautiful 更流畅更美。"},{"q":"7","answer":"A","options":["calm","break","lose","sell"],"explanation":"calm the mind 使心静下来。"},{"q":"8","answer":"B","options":["cloud","seal","river","song"],"explanation":"a seal with my name carved on it 刻有名字的印章。"},{"q":"9","answer":"C","options":["afraid","tired","proud","bored"],"explanation":"be proud of 为……自豪。"},{"q":"10","answer":"D","options":["throw","burn","lose","practise"],"explanation":"practise calligraphy 练习书法。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'How Porcelain Is Made', 'Have you ever wondered how a beautiful blue-and-white (1)____ bowl is made? The work begins with soft clay, which is shaped on a fast-spinning wheel. The maker must be (2)____ and careful, because one small mistake can ruin the whole piece. After the bowl has dried, an artist (3)____ a design onto it with a thin brush. Many bowls are decorated with dragons, flowers or (4)____ of mountains and rivers. The colours are mostly different (5)____ of blue. Next, the bowl is put into a very hot oven, where it is (6)____ for many hours. The great heat makes the clay hard and gives the surface a smooth (7)____. When the bowl comes out, the blue design shines (8)____ against the white. A single fine bowl can take many days to (9)____, so we should treat such works with (10)____. Each one is truly a small masterpiece.', 147, 2, '[{"q":"1","answer":"A","options":["porcelain","rubber","paper","plastic"],"explanation":"blue-and-white porcelain 青花瓷。"},{"q":"2","answer":"B","options":["sleepy","patient","rude","hungry"],"explanation":"patient and careful 既有耐心又细心。"},{"q":"3","answer":"C","options":["eats","drives","paints","sings"],"explanation":"paints a design 画上图案。"},{"q":"4","answer":"D","options":["prices","noises","holidays","pictures"],"explanation":"pictures of mountains and rivers 山水图案。"},{"q":"5","answer":"A","options":["shades","sounds","weeks","prices"],"explanation":"different shades of blue 深浅不同的蓝色。"},{"q":"6","answer":"B","options":["sold","baked","washed","driven"],"explanation":"it is baked in a hot oven 在热炉中烧制。"},{"q":"7","answer":"C","options":["sound","smell","surface","season"],"explanation":"a smooth surface 光滑的表面。"},{"q":"8","answer":"D","options":["slowly","quietly","sadly","brightly"],"explanation":"the design shines brightly 图案明亮地闪耀。"},{"q":"9","answer":"A","options":["make","throw","lose","break"],"explanation":"take many days to make 要花很多天来制作。"},{"q":"10","answer":"B","options":["anger","respect","hunger","fear"],"explanation":"treat with respect 以敬意对待。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'The Young Street Artist', 'Leo is sixteen, and he is already a well-known artist in our (1)____. He does not paint inside a museum or a (2)____. Instead, he creates huge, colourful pictures on old walls and bridges. Some neighbours think his (3)____ is messy, but most young people love it. Leo says that a grey, empty wall is (4)____ to look at, while a painted one can make people smile. Before he starts, he always asks the owner for (5)____, because he does not want to break any rules. Then he plans his picture (6)____ on paper. On painting day, his friends often come to (7)____ him work. Bit by bit, the dull wall is (8)____ into something bright and alive. Leo hopes that one day his art will (9)____ other young people to be creative. "Art should not be locked away," he says. "It should be (10)____ for everyone to enjoy."', 149, 2, '[{"q":"1","answer":"C","options":["kitchen","pocket","neighbourhood","future"],"explanation":"a well-known artist in our neighbourhood 社区里有名的艺术家。"},{"q":"2","answer":"D","options":["garden","station","market","gallery"],"explanation":"a museum or a gallery 博物馆或美术馆。"},{"q":"3","answer":"A","options":["graffiti","homework","breakfast","weather"],"explanation":"his graffiti is messy 他的涂鸦很乱。"},{"q":"4","answer":"B","options":["lovely","boring","tasty","loud"],"explanation":"an empty wall is boring 空墙很无趣,与下文 painted one 形成对比。"},{"q":"5","answer":"C","options":["breakfast","sleep","permission","weather"],"explanation":"ask for permission 请求许可。"},{"q":"6","answer":"D","options":["angrily","sadly","hungrily","carefully"],"explanation":"plans his picture carefully 仔细地规划。"},{"q":"7","answer":"A","options":["watch","sell","cook","drive"],"explanation":"come to watch him work 来看他作画。"},{"q":"8","answer":"B","options":["sold","turned","eaten","driven"],"explanation":"the wall is turned into something bright 墙被变成明亮的东西。"},{"q":"9","answer":"C","options":["forget","lose","encourage","sell"],"explanation":"encourage others to be creative 鼓励他人发挥创造力。"},{"q":"10","answer":"D","options":["late","dark","empty","free"],"explanation":"free for everyone to enjoy 人人都能免费欣赏。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'Our School Art Club', 'Every Friday afternoon, the art club in our school (1)____ in Room 12. About twenty students join, and our teacher, Mr Lin, makes each lesson great (2)____. Last month, we learned to draw faces, and this month we are (3)____ how to use colour. Mr Lin often shows us famous (4)____ by great painters and asks what we feel. He says there is no single right (5)____ in art, because everyone sees a picture in a different way. My best friend Mia is very (6)____ at drawing animals, while I prefer to paint flowers in a (7)____. At the end of each term, our work is (8)____ on the walls of the school hall for everyone to see. Last year, one of my paintings won a small (9)____, and I felt very happy. The art club has taught me to look at the world more (10)____ and to enjoy making beautiful things.', 152, 2, '[{"q":"1","answer":"A","options":["meets","sleeps","sells","drives"],"explanation":"the club meets in Room 12 社团在12号教室活动。"},{"q":"2","answer":"B","options":["noise","fun","trouble","danger"],"explanation":"great fun 很有乐趣。"},{"q":"3","answer":"C","options":["eating","driving","learning","sleeping"],"explanation":"we are learning how to use colour 我们在学如何用色。"},{"q":"4","answer":"D","options":["dinners","songs","games","paintings"],"explanation":"famous paintings by great painters 名家名画。"},{"q":"5","answer":"A","options":["answer","weather","ticket","price"],"explanation":"no single right answer 没有唯一正确答案。"},{"q":"6","answer":"B","options":["afraid","good","tired","late"],"explanation":"be good at drawing 擅长画画。"},{"q":"7","answer":"C","options":["river","cloud","vase","pocket"],"explanation":"flowers in a vase 花瓶里的花。"},{"q":"8","answer":"D","options":["eaten","sold","lost","shown"],"explanation":"our work is shown on the walls 作品展示在墙上。"},{"q":"9","answer":"A","options":["prize","storm","lunch","key"],"explanation":"won a small prize 获得了一个小奖。"},{"q":"10","answer":"B","options":["hungrily","closely","angrily","sleepily"],"explanation":"look at the world more closely 更仔细地观察世界。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required3', 'U4', 'A Day with a Sculptor', 'Last summer, I spent a day watching a (1)____ at work in his studio. His name is Mr Carter, and he makes statues out of stone and metal. When I arrived, a large (2)____ of a running horse was standing in the middle of the room. "Get a load of (3)____!" he said proudly, pointing at it. He explained that a good statue must show not only the shape of an animal but also its inner (4)____. All morning, he worked on the legs, slowly cutting the hard stone with his (5)____. Tiny bits of (6)____ covered the floor around him. He told me that one big statue can take several (7)____ to finish. He is very (8)____, and he never rushes his work. By the afternoon, the horse looked so real that it seemed ready to (9)____ off its stone base. I left the studio full of (10)____ for his amazing skill.', 153, 2, '[{"q":"1","answer":"C","options":["farmer","driver","sculptor","doctor"],"explanation":"watching a sculptor at work 看雕塑家工作。"},{"q":"2","answer":"D","options":["dinner","ticket","garden","statue"],"explanation":"a statue of a running horse 一座奔马的雕像。"},{"q":"3","answer":"A","options":["that","soup","rain","paper"],"explanation":"Get a load of that! 瞧瞧那个!固定说法。"},{"q":"4","answer":"B","options":["price","spirit","noise","pocket"],"explanation":"its inner spirit 它内在的神韵。"},{"q":"5","answer":"C","options":["songs","dreams","tools","prices"],"explanation":"cut the stone with his tools 用工具凿石头。"},{"q":"6","answer":"D","options":["music","weather","time","stone"],"explanation":"bits of stone covered the floor 石屑铺满地面。"},{"q":"7","answer":"A","options":["weeks","songs","prices","dreams"],"explanation":"take several weeks to finish 要花好几周才能完成。"},{"q":"8","answer":"B","options":["lazy","patient","angry","noisy"],"explanation":"very patient, never rushes 很有耐心,从不赶工。"},{"q":"9","answer":"C","options":["sing","sleep","gallop","cook"],"explanation":"ready to gallop off its base 仿佛要从底座飞奔而出。"},{"q":"10","answer":"D","options":["hunger","anger","fear","admiration"],"explanation":"full of admiration for his skill 满怀对其技艺的钦佩。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Where Shall We Go This Weekend?', '外研社版必修第三册 U4 · dialogue', 3, 'Mia: Tom, are you free this Saturday? I''d love to go and see some art.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·独白 Museum Announcement', '外研社版必修第三册 U4 · passage', 2, 'Welcome to the City Art Museum. Please note that our main hall is closed this morning, because a new exhibition is being prepared for the weekend. About thirty famous paintings are being hung on the walls right now, and the floor is being cleaned by our staff. While you wait, you are welcome to visit the porcelain room on the second floor, where blue-and-white bowls and vases are on show. The museum café is open all day, and a short film about Chinese calligraphy is shown there every hour. Thank you for your patience, and enjoy your visit.', '欢迎来到城市美术馆。主厅今天上午关闭,因为正在为周末布置新展览;约三十幅名画此刻正被挂上墙,地面也正由工作人员清扫。等候期间,欢迎参观二楼瓷器厅,那里展出青花碗与花瓶;咖啡馆全天开放,每小时放一部关于中国书法的短片。感谢耐心,祝参观愉快。', 'uk_female', '[{"q":"Why is the main hall closed this morning?","type":"choice","answer":"D","options":["The roof is being repaired.","There is no electricity.","A film is being made there.","A new exhibition is being set up."]},{"q":"What can visitors see on the second floor?","type":"choice","answer":"A","options":["Blue-and-white porcelain.","Modern sculptures.","Old photographs.","Famous self-portraits."]},{"q":"What is happening to the main-hall floor now?","type":"choice","answer":"B","options":["It is being painted.","It is being cleaned.","It is being sold.","It is being measured."]},{"q":"Where is the short film shown?","type":"choice","answer":"C","options":["In the main hall.","On the second floor.","In the museum café.","At the front gate."]},{"q":"What is the short film about?","type":"choice","answer":"D","options":["Street graffiti.","Stone sculpture.","Oil painting.","Chinese calligraphy."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 In Front of the Mona Lisa', '外研社版必修第三册 U4 · dialogue', 3, 'Anna: Ben, is this really the Mona Lisa? It''s much smaller than I expected.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·独白 The First Calligraphy Lesson', '外研社版必修第三册 U4 · passage', 2, 'Good afternoon, everyone, and welcome to your first calligraphy lesson. My name is Mr Zhang, and I have taught this art for twenty years. Today you will each get a brush, some black ink and a sheet of soft paper. Don''t worry if your first characters look messy — even great artists started that way. Remember to sit up straight and hold the brush gently. Calligraphy is not a race; it should make your mind feel calm and quiet. At the end of the class, the best work will be shown on the wall, and once a month we hold a small exhibition for parents. Now, let''s begin with a simple character meaning ''mountain''.', '张老师欢迎大家上第一节书法课,他教书法已二十年。今天每人会拿到一支笔、一些黑墨和一张软纸。第一次写得乱不要紧,连大艺术家也是这样起步的。要坐直、轻握笔。书法不是比赛,应让心安静下来。课末最佳作品会挂到墙上,每月还为家长办一次小展。现在从一个意为“山”的简单字开始。', 'uk_male', '[{"q":"How long has Mr Zhang taught calligraphy?","type":"choice","answer":"B","options":["For two years.","For twenty years.","For twelve years.","For thirty years."]},{"q":"What will each student receive today?","type":"choice","answer":"C","options":["A book and a pen.","A computer.","A brush, ink and paper.","A box of oil paint."]},{"q":"What does Mr Zhang say about messy first characters?","type":"choice","answer":"D","options":["It means they should stop.","It will never get better.","It is not allowed in class.","It is normal for beginners."]},{"q":"How should calligraphy make the mind feel?","type":"choice","answer":"A","options":["Calm and quiet.","Excited and busy.","Tired and bored.","Angry and worried."]},{"q":"How often is there a small exhibition for parents?","type":"choice","answer":"B","options":["Once a week.","Once a month.","Once a year.","Every single day."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 What Do You Think of Contemporary Art?', '外研社版必修第三册 U4 · dialogue', 3, 'Jill: Andrew, what did you think of that contemporary art show?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·独白 A Guide to Night-Shining White', '外研社版必修第三册 U4 · passage', 2, 'Ladies and gentlemen, please gather round this famous painting, Night-Shining White. It shows a single white horse, tied to a post, with burning eyes and kicking legs. Even after more than a thousand years, we can still feel its power and energy. The work is now kept here in our museum, and at the moment it is being protected by a special glass case. Notice how the artist captured not only the shape of the horse but also its wild spirit. Many visitors say the horse looks ready to break free and gallop away. Please do not use flash when taking photos, and let''s move quietly on to the next room.', '讲解员请大家围到名画《照夜白》前:画中一匹拴在柱上的白马,目光如火、奋蹄欲奔;历经千年仍能感到它的力量与活力。此画现藏于本馆,此刻正由特制玻璃罩保护。请注意艺术家不仅画出马的外形,还捕捉到它狂野的神韵;许多游客说这马仿佛要挣脱缰绳飞奔而去。拍照请勿用闪光灯,随后我们安静地前往下一展厅。', 'uk_male', '[{"q":"What does the painting show?","type":"choice","answer":"D","options":["A group of wild horses.","A horse and its rider.","An empty green field.","A single white horse."]},{"q":"How old is the painting, roughly?","type":"choice","answer":"A","options":["Over a thousand years old.","About a hundred years old.","Only ten years old.","Around five years old."]},{"q":"How is the painting protected at the moment?","type":"choice","answer":"B","options":["By a wooden box.","By a special glass case.","By a thick cloth cover.","By a high stone wall."]},{"q":"What did the artist capture besides the horse''s shape?","type":"choice","answer":"C","options":["Its exact age.","Its market price.","Its wild spirit.","Its owner''s name."]},{"q":"What does the guide ask visitors not to do?","type":"choice","answer":"D","options":["Touch the glass case.","Talk to each other.","Take any photos at all.","Use flash when taking photos."]}]'::jsonb, '[]'::jsonb, 'short', 'required3', 'U4', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write an Article about an Artwork(写一篇介绍艺术作品的短文)', 'Writing about an Artwork', '假设你是李华,学校英语墙报要介绍一件你喜欢的艺术作品。请用英语写一篇约100词的短文,内容包括:① 作品与艺术家的基本信息(名称/作者/年代);② 描述作品(画的是什么、颜色或感受);③ 你自己的评价和感受。注意:可恰当使用现在进行被动语态(is/are being done)描述展览或修复情况。', 'Suppose you are Li Hua. Your school English board wants a short piece about an artwork you like. Write an article (about 100 words) including: 1) basic facts about the work and the artist (name, painter, date); 2) a description of the work (what it shows, its colours or the feeling it gives); 3) your own comment and feelings. Try to use the present continuous passive (is/are being done) where it fits.', '["基本信息(This painting, called …, was created by … in …)","描述作品(It shows … mostly in shades of … / The work is now being displayed in …)","个人评价与感受(To me, it … / What I love most is …)","结构清晰:介绍—描述—评价三段,语言地道连贯"]'::jsonb, 70, 100, 'One of my favourite paintings is Sunflowers, created by Vincent van Gogh in 1889. It shows bright sunflowers standing in a simple vase, painted mostly in three shades of yellow. Some flowers are fresh and open, while others are beginning to fade, so the work feels warm and alive at the same time. Right now a copy of it is being displayed in our school library, and many students stop to look at it every day. To me, the painting is amazing because its warm colours seem to glow with light. Whenever I feel tired, I look at it and feel hopeful again.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["One of my favourite paintings is Sunflowers, created by Vincent van Gogh in 1889.","It shows bright sunflowers in a vase, painted mostly in three shades of yellow.","Right now a copy of it is being displayed in our school library.","Whenever I feel tired, I look at it and feel hopeful again."]'::jsonb, '[{"wrong":"The painting is displaying in our library now.","correct":"The painting is being displayed in our library now.","note":"画是被展出的对象,此刻进行用现在进行被动 is being displayed。"},{"wrong":"It shows sunflowers in three shade of yellow.","correct":"It shows sunflowers in three shades of yellow.","note":"three 后名词用复数 shades。"},{"wrong":"The painting was created by Van Gogh in 1889 year.","correct":"The painting was created by Van Gogh in 1889.","note":"in + 年份,不加 year。"}]'::jsonb, '【艺术作品介绍结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required3', 'U4', '{"title":"现在进行被动语态 is/are being done 速查","intro":"现在进行被动语态表示「此刻正在被进行」的动作,结构是 am/is/are + being + 过去分词。判断口诀:看时间(此刻进行?)定 being,看主语(单数/复数)定 is/are,看承受者定被动。","table":{"headers":["主语","结构 / 例句"],"rows":[["单数主语","is being + 过去分词:The painting is being cleaned now.(画此刻正被清洗)"],["复数主语","are being + 过去分词:The vases are being arranged now.(花瓶此刻正被摆放)"],["否定","is/are not being done:The hall is not being used today."],["一般疑问","Is/Are + 主语 + being done?:Is the statue being moved?"]]},"specialRules":[{"rule":"现在进行被动 vs 现在进行主动:承受者作主语用 being done,发出者作主语用 doing","mark":"A picture is being painted.（被动） / The artist is painting.（主动）"},{"rule":"现在进行被动 vs 一般现在被动:此刻进行用 is being done,习惯/经常用 is done","mark":"is being displayed now（此刻） / is displayed every day（习惯）"},{"rule":"只有及物动词有被动;being 后必须是过去分词,不能用原形或现在分词","mark":"is being built √ / is being build ×"},{"rule":"常见现在进行时标志词触发 being:now / right now / at the moment / look / listen","mark":"Look! It is being repaired."}],"why":["being 是 be 的现在分词,放在 is/are 后面表示「正在」;再加过去分词表示「被」。两层叠加,就是「此刻正在被……」。当说话人关注动作的承受者、或不知/不必说谁做时,就用被动。"],"gaokaoPoints":["语法填空高频:给出 now/at the moment + 动词原形,主语是承受者 → 填 is/are being + 过去分词。","易错点:把现在进行被动误写成一般现在被动(is done)或现在进行主动(is doing);先判时态再判语态。"],"examVsReal":[{"exam":"The bridge is being built now.（考试/书面）","real":"They''re building the bridge now.","note":"口语常用主动 they''re doing 替代被动,听起来更自然;考试爱考被动形式。"},{"exam":"A new exhibition is being prepared.（考试)","real":"We''re getting a new exhibition ready.","note":"真实英语口语常用 get sth ready 等说法,书面/正式场合多用被动。"}]}'::jsonb, 'fltrp');
